'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
let variant=OrionProgress.variant('reflection'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,placed=[],solved=false,hintDepth=0,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){const base=[[v%3,(v+1)%7],[(v+1)%3,(v+3)%7],[(v+2)%3,(v+5)%7]];return{axis:s,points:s===0?base:s===1?base.map(([x,y])=>[y,x]):[[4,v%3],[5,(v+1)%4],[6,(v+2)%5]]};}
function reflect([x,y],axis=stage){return axis===0?[6-x,y]:axis===1?[x,6-y]:[y,x];}
function key([x,y]){return y*7+x;}
function targetSide(x,y,axis=stage){return axis===0?x>3:axis===1?y>3:y>x;}
function onLine(x,y,axis=stage){return axis===0?x===3:axis===1?y===3:x===y;}
function resetTrial(){placed=[];solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('reflection')){variant=v;stage=0;resetTrial();}
function place(id){if(solved||!Number.isInteger(id)||id<0||id>48||!targetSide(id%7,Math.floor(id/7)))return;if(placed.includes(id))placed=placed.filter(n=>n!==id);else if(placed.length<3)placed.push(id);else{state='full';render();return;}state='ready';render();}
function check(){if(solved)return;const targets=challenge().points.map(p=>key(reflect(p)));if(placed.length!==3)state='count';else if(!targets.every(n=>placed.includes(n)))state='mirror';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('twinlight');}render();if(solved&&stage<2)$('next').focus();}
function hints(){const p=challenge().points[0],r=reflect(p);return[t('Imagine folding the garden along the silver line. A gold gem and its blue partner should meet.','想像沿銀線摺起花園。金寶石和它的藍寶石伙伴應該重合。'),stage===0?t('Stay in the same row. Count the same number of tile steps on the other side of the vertical line.','保持同一行，在直線另一邊數出相同格數。'):stage===1?t('Stay in the same column. Count the same number of tile steps below the horizontal line.','保持同一列，在橫線下方數出相同格數。'):t('Across this diagonal, swap row and column numbers. Row 2, column 5 reflects to row 5, column 2.','跨過這條斜線時，交換行和列的數字。例如第 2 行第 5 列，映到第 5 行第 2 列。'),t(`One partner: gold row ${p[1]+1}, column ${p[0]+1} reflects to row ${r[1]+1}, column ${r[0]+1}. Use the same rule for the other two.`,`其中一對：金寶石第 ${p[1]+1} 行第 ${p[0]+1} 列，映到第 ${r[1]+1} 行第 ${r[0]+1} 列。其餘兩顆也用相同規則。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,progress=stage+Number(solved),original=q.points.map(key);window.OrionDiscovery?.update(complete);document.title=t('The Mirror Garden · Orion','鏡影花園 · Orion');$('stageTitle').textContent=t(`Garden ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 座花園 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Mirror seals · ${progress} / 3`,`鏡影封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);let html='';for(let id=0;id<49;id++){const x=id%7,y=Math.floor(id/7),line=onLine(x,y),gold=original.includes(id),blue=placed.includes(id),active=targetSide(x,y),desc=gold?t('gold original','金色原圖'):line?t('mirror line','鏡線'):blue?t('blue gem; tap to remove','藍寶石；點按移除'):active?t('empty; tap to place','空格；點按放置'):t('original side','原圖一側');html+=`<button data-cell="${id}" class="${line?'line':gold?'original':blue?'placed':!active?'quiet':''}" ${!active||solved?'disabled':''} ${active?`aria-pressed="${blue}"`:''} aria-label="${t(`Row ${y+1}, column ${x+1}: ${desc}`,`第 ${y+1} 行第 ${x+1} 列：${desc}`)}">${gold?'◆':blue?'◇':line?stage===0?'│':stage===1?'─':'╲':'·'}</button>`;}$('board').innerHTML=html;
$('goal').textContent=stage===0?t('Restore the reflection across the vertical silver line.','修復銀色直線另一邊的鏡像。'):stage===1?t('Restore the reflection across the horizontal silver line.','修復銀色橫線另一邊的鏡像。'):t('Restore the reflection across the sloping silver line.','修復銀色斜線另一邊的鏡像。');
const line=stage===0?'M100 15V185':stage===1?'M15 100H185':'M15 15L185 185';let gems='';for(const [ids,col,filled] of [[original,'#f2cf86',true],[placed,'#91e2f1',false]])for(const id of ids){const x=25+(id%7)*25,y=25+Math.floor(id/7)*25;gems+=`<path d="M${x} ${y-7}L${x+7} ${y}L${x} ${y+7}L${x-7} ${y}Z" fill="${filled?col:'none'}" stroke="${col}" stroke-width="2"/>`;}$('preview').innerHTML=`<svg viewBox="0 0 200 200" aria-hidden="true"><rect x="5" y="5" width="190" height="190" rx="16" fill="#102d39" stroke="#66898c"/><path d="${line}" stroke="#dce7eb" stroke-dasharray="4 3" stroke-width="2"/>${gems}</svg>`;$('preview').setAttribute('aria-label',t('Overview of your gold and blue pattern. The large tile board is interactive.','金色與藍色圖案總覽。可在左方大格子操作。'));$('count').textContent=t(`Blue gems placed: ${placed.length} / 3`,`已放藍寶石：${placed.length} / 3`);const messages={ready:['Explore the mirror. Test when your three blue gems are ready.','探索月鏡。放好三顆藍寶石後便可測試。'],full:['Three blue gems are placed. Remove one before moving it to another tile.','已放好三顆藍寶石。先移除一顆，再放到另一格。'],count:['Each gold gem needs one blue partner. Place three blue gems.','每顆金寶石都需要一顆藍色伙伴。請放置三顆。'],mirror:['Not quite reflected yet. Check each gold gem’s partner across the silver line.','還未完全映照。看看每顆金寶石在銀線另一邊的伙伴。'],success:['The patterns meet in the moon mirror. A seal shines!','兩邊圖案在月鏡中重合，封印亮起了！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('twinlight')?t('Twinlight Sigil saved in your collection.','雙光符印已存入收藏。'):'';}
$('board').onclick=e=>{const button=e.target.closest('button[data-cell]');if(!button)return;const id=Number(button.dataset.cell);place(id);$('board').querySelector(`[data-cell="${id}"]`)?.focus();};$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('board').querySelector('button:not(:disabled)')?.focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('reflection',variant);observedVariant=OrionProgress.variant('reflection');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('twinlight');render();};function syncProgress(){const v=OrionProgress.variant('reflection'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('twinlight')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
